import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d as c,i as A,S as p}from"./chunks/framework.InCnrqk-.js";const M=JSON.parse('{"title":"局部性原理","description":"","frontmatter":{"title":"局部性原理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/locality-principle.md","filePath":"cs/locality-principle.md","lastUpdated":1789023840000}'),d={name:"cs/locality-principle.md"};function h(E,a,B,m,_,C){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="局部性原理" tabindex="-1">局部性原理 <a class="header-anchor" href="#局部性原理" aria-label="Permalink to &quot;局部性原理&quot;">​</a></h1><div class="epigraph"><p>程序在短时间内只用地址空间的一小块；没有这条经验规律，SRAM 与 DRAM 之间的速度差就无法被藏住。</p><footer>—— 据 Denning, The Working Set Model for Program Behavior, CACM 1968；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/ipc-util">上一课</a>把 CPU 时间写成指令数 × CPI × 周期，停顿可以任意加项。五级核假定 MEM 级一拍完成访存。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>已经说明：大容量用 DRAM，随机访问要许多纳秒，SRAM 快但贵、小。本课不重讲电容刷新，也不从「存储器是什么」另起。缺口是：若每次 load 都付 DRAM 延迟，CPI 里的停顿项会淹没流水线的全部收益。本课只钉时间局部性与空间局部性，作为后课 cache 的前提。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流水线把计算叠起来以后，瓶颈从 ALU 挪到访存。DRAM 做不到每拍随机读。<a href="/cs/asymptotic-notation">渐近记号</a>描述的是步数，不描述哪一次访问碰巧挨着上一次。缺口不是新的器件，而是<strong>程序的地址轨迹不是均匀撒在整个空间上</strong>。</p><p>时间局部性：刚用过的地址很快再用。空间局部性：刚用过的地址附近很快被用。循环扫数组、顺序取指，都是这两条的实例。本课不引入 cache 行、不引入页。</p><p><span class="marginnote">Denning 的工作集是「最近 \\(T\\) 时间内触到的页集合」。本课先用局部性一词，工作集的定量在虚拟内存课再引用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把访存看成地址序列 \\(a_1,a_2,\\ldots\\)。时间局部性说：若 \\(a_t=x\\)，则近期内 \\(x\\) 再次出现的概率远高于均匀随机。空间局部性说：\\(x\\) 附近的字（同一块、同一页）也会在近期出现。层次存储器的策略因此是：把最近用过的块放进小而快的 SRAM，命中则延迟接近寄存器，缺失才付 DRAM。</p>',9)),(e(),s(p,null,{default:r(()=>[A(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROG%5B%22%E7%A8%8B%E5%BA%8F%E5%9C%B0%E5%9D%80%E8%BD%A8%E8%BF%B9%22%5D%20--%3E%20LOC%5B%22%E6%97%B6%E9%97%B4%E4%B8%8E%E7%A9%BA%E9%97%B4%E5%B1%80%E9%83%A8%E6%80%A7%22%5D%0A%20%20LOC%20--%3E%20SRAM%5B%22%E5%B0%8F%E8%80%8C%E5%BF%AB%20SRAM%22%5D%0A%20%20LOC%20--%3E%20DRAM%5B%22%E5%A4%A7%E8%80%8C%E6%85%A2%20DRAM%22%5D%0A%20%20SRAM%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%EF%BC%9ACPI%20%E5%81%9C%E9%A1%BF%E5%B0%8F%22%5D%0A%20%20DRAM%20--%3E%20MISS%5B%22%E7%BC%BA%E5%A4%B1%EF%BC%9A%E5%81%9C%E9%A1%BF%E5%A4%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>本课只承认这条经验规律可被利用；块多大、怎么映射，是<a href="/cs/direct-mapped-cache">直接映射 Cache</a>的缺口。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了局部性，平均访存时间可以写成命中时间 + 缺失率 × 缺失代价，再进 CPI 公式。没有局部性，缺失率接近 1，层次没有意义。取指天然有空间局部性；数据是否有，取决于布局——后课链表会把它打断。</p><p>局部性是程序性质，不是硬件保证。编译器改循环顺序、程序员改数据结构，都会改轨迹。硬件只能赌「多数程序像这样」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论 cache 一致性，不引入 TLB，不把局部性说成数学定理。反例存在：大步长跳扫、指针追逐，空间局部性很差。后课会在链表、稀疏图里回到这条边界。</p><p>也不要把局部性写成「cache 的定义」。cache 是实现；局部性是为什么实现能赢。后课默认：谈到存储器层次，先假定程序有可用的时间与空间局部性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DRAM 延迟会毁流水线收益；局部性让小 SRAM 接住大多数访问。</li><li>时间：再用同一地址；空间：用邻近地址。</li><li>映射、写策略、缺失分类都是后课的缺口。</li><li>出处：Denning, <em>CACM</em> 1968；Hennessy and Patterson, <em>CA:AQA</em> 存储器层次。</li></ul>',9))])}const f=o(d,[["render",h]]);export{M as __pageData,f as default};
